-- อัตราเบี้ยประกันภัย พ.ร.บ. ตามประเภทระบบขับเคลื่อน/เจ้าของ/การใช้รถ
-- car_owner_type_id, car_usage_category_id เป็น NULL ได้ — legacy ใช้ id=9 แทนความหมาย "ไม่ระบุ/ทุกประเภท"
-- (wildcard) ซึ่งไม่ตรงกับแถวจริงใน car_owner_types/car_usage_categories เลย จึง map เป็น NULL แทน
CREATE TABLE car_vehicle_tariffs (
    id                       UUID          PRIMARY KEY DEFAULT uuidv7(),
    code                     VARCHAR(20)   NOT NULL,
    name_th                  VARCHAR(200)  NOT NULL,
    tariff_type              VARCHAR(5)    NOT NULL,
    car_powertrain_type_id   UUID          NOT NULL REFERENCES car_powertrain_types(id),
    car_owner_type_id        UUID          REFERENCES car_owner_types(id),
    car_usage_category_id    UUID          REFERENCES car_usage_categories(id),
    seat                     INT,
    cc                       NUMERIC(7, 2),
    gvw                      INT,
    tariff_check_min         NUMERIC(7, 2),
    tariff_check_max         NUMERIC(7, 2),
    net_prem                 NUMERIC(10, 2),
    stamp                    NUMERIC(10, 2),
    vat                      NUMERIC(10, 2),
    total                    NUMERIC(10, 2),
    asset_group              VARCHAR(20),
    body_type                VARCHAR(100),
    use_of_motor             VARCHAR(200),
    active_flag              BOOLEAN       NOT NULL DEFAULT TRUE,
    created_at                TIMESTAMPTZ   NOT NULL,
    created_by                 VARCHAR(100)  NOT NULL,
    updated_at                  TIMESTAMPTZ   NOT NULL,
    updated_by                   VARCHAR(100)  NOT NULL,
    version                       BIGINT        NOT NULL DEFAULT 0,

    CONSTRAINT uq_car_vehicle_tariffs_code UNIQUE (code)
);

CREATE INDEX idx_car_vehicle_tariffs_powertrain ON car_vehicle_tariffs(car_powertrain_type_id);
CREATE INDEX idx_car_vehicle_tariffs_owner      ON car_vehicle_tariffs(car_owner_type_id);
CREATE INDEX idx_car_vehicle_tariffs_usage      ON car_vehicle_tariffs(car_usage_category_id);

COMMENT ON TABLE car_vehicle_tariffs IS 'อัตราเบี้ยประกันภัยรถยนต์ภาคบังคับ (พ.ร.บ.) ตามระบบขับเคลื่อน/ประเภทเจ้าของ/ลักษณะการใช้รถ และช่วงแรงม้า/น้ำหนัก';

-- seed จากข้อมูลจริง legacy master.CarVehicleTariff (143 แถวในไฟล์ แต่มี code ซ้ำ 1 คู่ '2.40A' —
-- แถวเก่า active_flag=0 ถูกแทนที่ด้วยแถวใหม่ active_flag=1 เก็บเฉพาะแถวที่ active จริง เหลือ 142 แถว)
